  _routerCheckTransition(p.status, ROUTER_PROFILE_MATURITY_V2.RETIRED);
  const now = Date.now();
  p.status = ROUTER_PROFILE_MATURITY_V2.RETIRED;
  p.updatedAt = now;
  if (!p.retiredAt) p.retiredAt = now;
