  const now = Date.now();
  d.status = ROUTER_DISPATCH_LIFECYCLE_V2.DISPATCHING;
  d.updatedAt = now;
  if (!d.dispatchedAt) d.dispatchedAt = now;
  return { ...d, metadata: { ...d.metadata } };
