  _dispatchCheckTransition(d.status, ROUTER_DISPATCH_LIFECYCLE_V2.COMPLETED);
  const now = Date.now();
  d.status = ROUTER_DISPATCH_LIFECYCLE_V2.COMPLETED;
  d.updatedAt = now;
  if (!d.settledAt) d.settledAt = now;
  return { ...d, metadata: { ...d.metadata } };
