  afterEach(() => {
    Object.assign(_deps, originalDeps);
    vi.clearAllMocks();
  });

  it("includes claude backend when claude CLI is found", () => {
    _deps.execSync = vi.fn((cmd) => {
      if (cmd.includes("claude")) return "2.0.0";
